import unreal
rows=[]
for manager in unreal.ObjectIterator(unreal.PlayerCameraManager):
    try:
        world=manager.get_world()
        world_path=world.get_path_name() if world else ''
        if 'UEDPIE' in world_path:
            rows.append({'path':manager.get_path_name(),'world':world_path,'location':str(manager.get_camera_location()),'rotation':str(manager.get_camera_rotation())})
    except Exception as error:
        rows.append({'error':str(error)})
print('M2A_SIE_CAMERAS='+repr(rows))
